const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taiwan = ee.Geometry.Point([121.0, 23.5]).buffer(150000); // ~150km radius around Taiwan center

  const period1Start = '2020-02-10';
  const period1End = '2020-02-26'; // Exclusive end date
  const period2Start = '2020-04-20';
  const period2End = '2020-05-13'; // Exclusive end date

  // 2. Data Acquisition
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  const col1 = no2Collection
    .filterDate(period1Start, period1End)
    .filterBounds(taiwan);

  const col2 = no2Collection
    .filterDate(period2Start, period2End)
    .filterBounds(taiwan);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Period 1 (Feb 10-25): ${size1} images`);
  console.log(`Period 2 (Apr 20-May 12): ${size2} images`);

  if (size1 === 0 || size2 === 0) {
    console.log("Missing data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Quality masking and aggregation
  function maskQuality(image) {
    const qa = image.select('tropospheric_NO2_column_number_density');
    return image.updateMask(qa.gt(-1e10)); // Basic validity check
  }

  const mean1Image = col1.map(maskQuality).mean();
  const mean2Image = col2.map(maskQuality).mean();

  // 4. Calculate statistics
  const stats1 = mean1Image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = mean2Image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taiwan,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const mean1 = stats1.tropospheric_NO2_column_number_density_mean;
  const count1 = stats1.tropospheric_NO2_column_number_density_count;
  const mean2 = stats2.tropospheric_NO2_column_number_density_mean;
  const count2 = stats2.tropospheric_NO2_column_number_density_count;

  console.log(`Period 1: Mean NO2 = ${mean1}, Valid pixels = ${count1}`);
  console.log(`Period 2: Mean NO2 = ${mean2}, Valid pixels = ${count2}`);

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1 === null || mean1 === undefined || isNaN(mean1) || 
      mean2 === null || mean2 === undefined || isNaN(mean2)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  const increase = mean2 > mean1;
  const percentChange = ((mean2 - mean1) / mean1 * 100).toFixed(2);

  console.log(`Change: ${percentChange}%`);

  if (increase) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
